target.css:
:root {
  --ink: #243631;
  --paper: #fffdf5;
  --line: #bdd4c7;
  --mint: #dff0e5;
  --green: #28765a;
}

.workshop-pass {
  width: 460px;
  box-sizing: border-box;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.pass-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: var(--mint);
  border-bottom: 1px solid var(--line);
}

.pass-type {
  color: var(--green);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.pass-status {
  color: var(--ink);
  font-size: 12px;
  font-weight: 600;
}

.pass-copy {
  padding: 15px 14px 13px;
}

.pass-copy h2 {
  margin: 0 0 5px;
  color: var(--ink);
  font-size: 21px;
  line-height: 1.1;
}

.pass-copy p {
  margin: 0;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.45;
}

.pass-footer {
  padding: 0 14px 14px;
}

.pass-footer button {
  padding: 9px 13px;
  color: var(--paper);
  background: var(--green);
  border: 0;
  border-radius: 7px;
  font-size: 14px;
  font-weight: 700;
}
